import{_ as a,o as s,c as o,a3 as e}from"./chunks/framework.DdpBa4_E.js";const t="/ReadBooks/assets/image-102.hK4Vgxc8.jpg",i="/ReadBooks/assets/image-104.RHgw6TSX.jpg",l="/ReadBooks/assets/image-105.fl52zcC3.jpg",r="/ReadBooks/assets/image-112.B4ZXSRt4.jpg",n="/ReadBooks/assets/image-113.JlaTCK55.jpg",g="/ReadBooks/assets/image-114.CBlnBwkT.jpg",d="/ReadBooks/assets/image-115.B3duQ10B.jpg",m="/ReadBooks/assets/image-118.-CyBys58.jpg",c="/ReadBooks/assets/image-119.BQfF6gYF.jpg",_="/ReadBooks/assets/image-128.C0zX2yla.jpg",h="/ReadBooks/assets/image-132.CQdW55PK.jpg",k="/ReadBooks/assets/image-098.XSzfa0mW.jpg",B="/ReadBooks/assets/image-106.OtDKaHa-.jpg",u="/ReadBooks/assets/image-108.BIc0e2Od.jpg",b="/ReadBooks/assets/image-099.CkmhOhP6.jpg",y="/ReadBooks/assets/image-107.BLSy2QPZ.jpg",z="/ReadBooks/assets/image-100.CEG44KKM.jpg",q="/ReadBooks/assets/image-101.Jms3oDUz.jpg",R="/ReadBooks/assets/image-109.BW8ODvcW.jpg",j="/ReadBooks/assets/image-110.DHWr6vBG.jpg",f="/ReadBooks/assets/image-121.DxW1pFFl.jpg",P="/ReadBooks/assets/image-111.9J1gCYAT.jpg",I="/ReadBooks/assets/image-116.DOTEiJWW.jpg",x="/ReadBooks/assets/image-117.Bjtsluk9.jpg",A="/ReadBooks/assets/image-120.BYuFVulR.jpg",C="/ReadBooks/assets/image-127.DOUb34Ud.jpg",G="/ReadBooks/assets/image-124.l-8qI2WT.jpg",T="/ReadBooks/assets/image-125.DbmjWhhp.jpg",S="/ReadBooks/assets/image-129.KvzABuvJ.jpg",D="/ReadBooks/assets/image-103.Cv6c0X9Z.jpg",E="/ReadBooks/assets/image-126.Bq_Zmz1E.jpg",O="/ReadBooks/assets/image-130.2paUa8nX.png",W="/ReadBooks/assets/image-131.C9brmoHz.png",F="/ReadBooks/assets/image-122.Bh5Q1z4U.jpg",K="/ReadBooks/assets/image-123.C_escGqb.jpg",V=JSON.parse('{"title":"第八章 改变首尔的六大经营战略","description":"","frontmatter":{},"headers":[],"relativePath":"books/jingying-weilai/11-第八章改变首尔的六大经营战略.md","filePath":"books/jingying-weilai/11-第八章改变首尔的六大经营战略.md","lastUpdated":1795076791000}'),v={name:"books/jingying-weilai/11-第八章改变首尔的六大经营战略.md"};function w(H,p,J,U,X,M){return s(),o("div",null,[...p[0]||(p[0]=[e('<h1 id="第八章-改变首尔的六大经营战略" tabindex="-1">第八章 改变首尔的六大经营战略 <a class="header-anchor" href="#第八章-改变首尔的六大经营战略" aria-label="Permalink to &quot;第八章 改变首尔的六大经营战略&quot;">​</a></h1><h2 id="一、效率——截住流出去的钱" tabindex="-1">一、效率——截住流出去的钱 <a class="header-anchor" href="#一、效率——截住流出去的钱" aria-label="Permalink to &quot;一、效率——截住流出去的钱&quot;">​</a></h2><h3 id="转换思路能省钱" tabindex="-1">转换思路能省钱 <a class="header-anchor" href="#转换思路能省钱" aria-label="Permalink to &quot;转换思路能省钱&quot;">​</a></h3><p><img src="'+t+'" alt="清溪川绿头鸭" loading="lazy"></p><p>清溪川绿头鸭</p><p><img src="'+i+'" alt="首尔林效果图" loading="lazy"></p><p>首尔林效果图</p><p><img src="'+l+'" alt="参加首尔林绿化活动" loading="lazy"></p><p>参加首尔林绿化活动</p><p><img src="'+r+'" alt="李明博与青年学生合影" loading="lazy"></p><p>李明博与青年学生合影</p><p><img src="'+n+'" alt="李明博与儿童在笑脸留言牌活动现场合影" loading="lazy"></p><p>李明博与儿童在笑脸留言牌活动现场合影</p><p><img src="'+g+'" alt="李明博探望老人" loading="lazy"></p><p>李明博探望老人</p><p><img src="'+d+'" alt="李明博与轮椅使用者握手交流" loading="lazy"></p><p>李明博与轮椅使用者握手交流</p><p><img src="'+m+'" alt="李明博在港区指向集装箱货轮" loading="lazy"></p><p>李明博在港区指向集装箱货轮</p><p><img src="'+c+'" alt="李明博在传统木构建筑旁" loading="lazy"></p><p>李明博在传统木构建筑旁</p><p><img src="'+_+'" alt="李明博在群众中作胜利手势" loading="lazy"></p><p>李明博在群众中作胜利手势</p><p><img src="'+h+'" alt="李明博的母亲" loading="lazy"></p><p>李明博的母亲“下一任市长光是偿还李明博留下的债务也忙不过来啊。光一个清溪川就花了3600亿韩元，还有首尔广场、交通改造、首尔林，这些工程都花了多少钱啊？”</p><p>这番话出自一位出租车司机之口，是秘书室的职员传达给我的。那名职员有些不快地说：“民选三期市政府一边努力做项目，一边还偿还了地铁施工的一半债务，每年能节省数千亿元的预算。这些事实市民们根本就不知道。”</p><p>我只是笑笑，没说什么，因为那样的话我也不是第一次听说了。</p><p>“这么干下去，首尔迟早会破产！”</p><p>“债务怎么可能减少？我看只会增加更多！”</p><p>不仅在市民中间有这样的传言，一开始连公务员内部也有许多质疑声。但不到一年，公务员内部的质疑声就消失了，因为大家都切身感受到了节约预算的成果。</p><p>我一上任就强调节约预算，支持者寥寥无几。连亲近的幕僚也忠告我说：</p><p>“市长，咱们怎么可能一边高喊节约，一边大力促进复原清溪川、改造大众交通、扩大文化福利项目呢？”</p><p>他们建议要么减少项目，要么降低预算节约额，二者选其一。</p><p>但我不能同意他们的想法。</p><p>“我们一直在仔细研究以前的预算使用情况，看到最多的就是浪费性预算。光是节省这一部分就是一个不小的数目。和以前浪费的数目相比，我们要推进的新项目其实花不了多少钱。”</p><p>我这样回答他们。</p><p>以前，政府在预算制作程序上太过疏忽。本来应该进行仔细调查后再制定的预算，大多就是按照上一年度的习惯照本宣科。即使情况有所变化，也还是沿袭惯例，所以经常多出一些用不到预算。如果我们能把这些不必要的浪费杜绝掉，节约预算就不是一件难事。</p><p>事实上，我们也确实取得了成功。</p><p>“李明博有什么秘诀，可以节约那么多预算？”</p><p>这是很多人都想知道的。</p><p>第一个原则是：在项目实施过程中发挥创意。最需要警惕的就是按照惯例、贪图方便的工作方式。</p><p>“怎么才能花更少的钱、获得更高的效率？”</p><p>首尔的公务员们养成了这样一种思考方式。</p><p>在复原清溪川工程的实施过程中，我们遇到了既要拆除三一高架桥，又要确保道路通畅的问题。一旦拆除高架路，行车道必然会减少。代行方案是把一部分行车道改成P字型。为了补充减少的行车道，就要在原先的人行道上加以扩充。而且为了确保道路占地，还需要拆除路边建筑。可以想见，以这种方式扩充道路的话，光是拆迁费就是一笔很大的支出。</p><p>“必须拆除路边的建筑吗？有没有其他更好的方法？“有关负责人也为这笔巨大的补偿费而大伤脑筋。一番苦思冥想之后，创意就出来了。“不需要拆除所有的建筑，我们只要把一部分建筑改成“T”型就可以了，利用凹进去的一部分作为人行道。”就这样一个简单的创意，节省了数百亿韩元的建筑拆迁费。如果按以前的惯例行事，浪费是难以避免的。由此可见，只要改变一下思路，发挥一点创意，就有可能节约预算。第二个原则是：彻底考虑项目实施的妥当性。在变更设计或技术时，我们经常会讨论：“一定要用那种方法吗？”地铁9号线区间设计招标时就发生过这样一件事。当时设计招标工作已经接近尾声，但是我发现，各个区间的金额差异很大。“为什么相同的区间，金额相差这么多？”“因为招标的方式不多。一个是承包，另一个是联合。”“为什么招标的方式不同？就算是招标的方式不同，就应该有这么大的差异吗？”“这个……”负责人以难堪的表情搪塞过去了。后来经过打听才知道，有区间之所以金额高，是因为地铁内外部装修用的都是高级材料。我问相关负责人：“使用这么高级材料，理由是什么？”对方无言以对。最终，中标企业重新制定了那个区间的装修设计方案，比最初预算节约了20%以上。在建设地铁站残疾人专用电梯项目中，也发生过类似的情况。在我担任市长初期，曾经发生过残疾人从地铁电梯上跌落致死的事件。我亲自去现场察看了残疾人用电梯，发现果然存在着安全隐患和不方便之处。“要确实改善残疾人公共设施。首先在各个地铁站设置方便残疾人和老弱者使用的电梯。”我做出指示后，相关部门便着手制定改进方案和项目预算。但是结果，预算金额大大超出我的想象。“怎么会需要这么多呢？”我召集人员对设计方案进行讨论，仔细核算各部分金额，答案很快出现了。地铁区间的电梯是为老弱病残者准备的，需要使用的人数并不多，一天平均使用的次数也不多。但是，设计方案却是按照多数人都乘坐的高层建筑用电梯的标准计算。“供老弱病残者使用的地铁电梯有必要和一次能容纳几十人的高级公寓或办公大楼的电梯一样吗？不需要那么华丽，也不要求速度特别快。”对设计方案进行合理修改之后，又省下了一笔可观的预算。地铁残疾人用电梯的设置是一项面向未来的投资。如果单纯比较投入金额，也许给首尔市的残疾人每人购买一辆汽车更加经济，但是考虑到社会高龄化趋势，站在市民福利立场上，我们认为还是应该把资金投入这样的基础设施。无论什么项目，只要从开始阶段就彻底考虑各个环节是否处理妥当，如何更有效地使用预算，就有可能做到最大化的节约。</p><h3 id="把税收当做自己的钱来用" tabindex="-1">把税收当做自己的钱来用 <a class="header-anchor" href="#把税收当做自己的钱来用" aria-label="Permalink to &quot;把税收当做自己的钱来用&quot;">​</a></h3><p>“能这么快晋升的原因是什么？“这是我在现代建设公司任职时，经常被问到的一个问题。每次我的回答都是一样的：“因为我把公司的钱当做自己的钱，把自己当做公司的主人。”把公司的钱当做自己的钱一样珍惜，实质上就是全身心地投入工作。在出任首尔市长后，我反复向公务员们强调的也是类似的话：“我们应该把税收当做自己的钱一样使用。企业的目标是赚钱，花钱投资最终目标也是赚钱，但是，公务员的职责是用好每一分税金。从这个层面上说，公务员只需要做企业一半的事情，所以应该做得更好。”一个企业如果经营不好，受到损失的只是企业成员而已，但是，如果首尔的公务员不能有效地使用税收，那么遭受损失的将是1000万首尔市民。从这个意义上说，公务员比企业经营者担负的责任要大得多。这也是我之所以提出公务员应当把税收当做自己的钱来用的首要原因。但现实情况又是如何呢？浪费税收的事例不胜枚举。京釜高速铁路最初的工程预算是5兆韩元，但事实上花了多少钱？这么大的数额，也许能救活许多陷入资金困难的中小企业，也许能更换全部中小学校的教育设施。执行政策的公务员如果具有主人翁意识，把税收当做自己的钱一样使用，那么很多不必要花费是可以被阻拦下来的。首尔在2005年一年时间里就节约了大约8000亿韩元的预算。听到这个数字，肯定有人会搔头：“到底做了什么就节省了8000亿？难道说以前的预算都是像气球一样吹起来吗？”但这的确是我们通过合理的方式、减少不必要浪费所获得成果。反推上去便可想见，以前的预算浪费有多么严重。首尔市政府把税收预算分为分配预算阶段、合同制定阶段和项目执行阶段，实施一环扣一环的节约方案。在分配预算阶段通过制定具体的事业计划、进行事业量的调查达到节约目的，在合同制定阶段通过讨论技术妥当性、成本计算和决定合同方法等方式达到节约目的，在项目执行阶段则是通过改进设计方案和工作方式、引入新的施工方法等，为节省每一分钱而努力。这8000亿就是用这样的方式和态度挤出来的。2006年，首尔的地铁首次实现了盈利。在我就任初接近5兆韩元的地铁运营负债减少了2.1兆韩元，这都是全体公务员努力的结果。如果不注重节约预算，首尔的地铁费用将不得不再一次增加。之所以能减少地铁工程债务，就是因为实行了一定程度的责任经营制。地铁运营负责人不得不通过附属项目，在增加收益方面下工夫。这也是民选三期首尔市政府提倡企业经营意识结出的硕果。</p><p>在我经营首尔的四年里，节约预算的努力是提高行政效率的最好体现，对此我感到骄傲。把取自市民的税收当做自己的钱来用，这就是最有效率的方式。</p><h2 id="二、品牌—营销-首尔株式会社" tabindex="-1">二、品牌—营销“首尔株式会社” <a class="header-anchor" href="#二、品牌—营销-首尔株式会社" aria-label="Permalink to &quot;二、品牌—营销“首尔株式会社”&quot;">​</a></h2><h2 id="用太极旗覆盖市政厅" tabindex="-1">用太极旗覆盖市政厅 <a class="header-anchor" href="#用太极旗覆盖市政厅" aria-label="Permalink to &quot;用太极旗覆盖市政厅&quot;">​</a></h2><p>“每年10月3日开天节，我都把具有特殊意义的太极旗挂在欧洲唯一的李烈士纪念馆（Yi Jun Peace Museum）的正面……我只是一个普通的爱国者，但我每天早上都会在李烈士纪念馆升起太极旗。从1995年开馆以来，在过去的10年里，除了周日以外，我每天都把这面国旗升起在异国的古屋上，心里默默地、大声地喊着：‘大韩民国万岁！’”</p><p><img src="'+k+'" alt="在荷兰海牙李儁烈士纪念馆签访问册" loading="lazy"></p><p>在荷兰海牙李儁烈士纪念馆签访问册这是2005年10月，荷兰海牙“李烈士纪念馆”管理人李先生写给我的一封信。</p><p>2005年8月15日，首尔市为了纪念光复60周年，用3600面太极旗覆盖了市政厅本馆。当时使用的第一号太极旗就捐赠给了“李烈士纪念馆”。因此，李先生给我寄来了这封感谢信。</p><p><img src="'+B+'" alt="环境马拉松活动" loading="lazy"></p><p>环境马拉松活动</p><p><img src="'+u+'" alt="美丽店铺活动" loading="lazy"></p><p>美丽店铺活动为纪念光复60周年，在市政厅举行太极旗装置活动就是以营销城市品牌为思路策划的。在全球化背景下，强化一个国家或一个城市的品牌概念非常重要。</p><p>“什么样的活动能激起市民们的民族自豪感呢？”</p><p><img src="'+b+'" alt="为世界杯加油" loading="lazy"></p><p>为世界杯加油</p><p><img src="'+y+'" alt="首尔分享爱自愿活动" loading="lazy"></p><p>首尔分享爱自愿活动这是我们在活动策划阶段考虑的中心问题。光复60周年意义非凡。大韩民国经过建国、近代化、产业化、民主化，一直到现在接近发达国家的门槛，首都首尔在整个历程中一直起着领头作用。作为全国近代化和产业化的中心、1988年奥运会和2002年韩日世界杯的举办地，首尔在提升大韩民国的形象上一直站在最前沿，首尔市民也因此充满自豪感。但是最近几年，因为首都搬迁计划，这种自豪感和象征性渐渐减弱了。</p><p>在策划光复60周年庆典活动时，我们的目标就是想让首尔市民重新找到自豪感，提升首尔的城市品牌形象。</p><p><img src="'+z+'" alt="旧韩国中央厅悬挂太极旗的白天景象" loading="lazy"></p><p>旧韩国中央厅悬挂太极旗的白天景象</p><p><img src="'+q+'" alt="旧韩国中央厅悬挂太极旗的夜间景象" loading="lazy"></p><p>旧韩国中央厅悬挂太极旗的夜间景象“是不是可以通过太极旗的形象，让市民们联想到2002年世界杯时大家聚集在市政厅前面的广场上呐喊助威的情景？”</p><p>从这个创意出发，最终诞生了用太极旗覆盖市政厅本馆的方案。</p><p>“市政厅大楼以及前面的广场对首尔市民来说具有浓厚的象征性。再说，市政厅大楼不是在日本侵略时期盖的吗？如果我们用太极旗覆盖整个本馆，然后在广场上演奏《韩国幻想曲》，一定会令市民们印象深刻，油然生出一种自豪感。”</p><p>方案确定了，接下来便是执行问题。怎么用太极旗覆盖市政厅本馆呢？一开始的想法是用一面巨大的太极旗，但执行起来有困难，因为市政厅大楼的形态和太极旗的比例不相符。还有人提议，在市政厅前面支一个大支架，然后把太极旗挂在支架上。这个方案也不理想。</p><p>“是不是想得太难了？为什么一定要用一面太极旗呢？我们可以在市政厅大楼上拉一些晾衣绳那样的绳子，在上边挂很多太极旗，让无数太极旗随风飘扬起来，这不是很好吗？”</p><p>我在讨论会上提出自己的想法。以我的意见为基础，年轻的活动家们开始了具体布置。考虑到市政厅大楼的形态，最终决定使用一面大太极旗和3600面小太极旗。</p><p>首尔市纪念光复60周年活动引起了市民们的强烈反响。8月15日那一天，早早赶来的2万多市民把首尔广场围得水泄不通。在首尔广场上，世界著名指挥家郑明勋率领首尔交响乐团圆满完成了第一次演出。这次活动不仅在国内反应良好，日本NHK电视台等媒体也大张旗鼓地报道了首尔的太极旗和爱国歌活动。</p><p>活动结束后，我们把这3600面小太极旗分发给了市民。原本是想免费送给市民的，但由于担心引起政治上的误解，最后决定采用邮寄的方式送给提出申请的市民，每件只收取1000韩元的邮寄费。从市民们的踊跃申请中，我们体会到了这次活动带给他们的深深感动。</p><h2 id="改-汉城-为-首尔" tabindex="-1">改“汉城”为“首尔” <a class="header-anchor" href="#改-汉城-为-首尔" aria-label="Permalink to &quot;改“汉城”为“首尔”&quot;">​</a></h2><p><img src="'+R+'" alt="在利川传统市场" loading="lazy"></p><p>在利川传统市场</p><p><img src="'+j+'" alt="在济州民俗市场" loading="lazy"></p><p>在济州民俗市场人们常说现在是一个“品牌时代”，因为品牌价值是决定市场成败的关键要素。美国营销协会对“品牌”的定义是：意在识别一个或一群卖主的商品或服务，并将其与竞争对手的商品或服务区分开来的名称、术语、标识、象征、设计及其总和。</p><p><img src="'+f+'" alt="访问纽约" loading="lazy"></p><p>访问纽约城市品牌的概念也是一样。象征一个城市的名称、环境、符号、文物、庆典、市民的亲切度等等所有这些因素合起来，就形成了这个城市的品牌形象。例如，巴黎的品牌就是城市风景、艺术氛围、文化传统与巴黎市民生活协调的整体形象。巴黎为了强化这样的品牌形象，运用了文化商品、城市象征等各种品牌战略。纽约、伦敦、罗马、新加坡等城市也在城市品牌营销方面下足了工夫。</p><p>“现在我们应该把首尔的城市形象、城市品牌、城市历史培养成我们的文化资本。”</p><p><img src="'+P+'" alt="访问大宇巨济造船所" loading="lazy"></p><p>访问大宇巨济造船所</p><p><img src="'+I+'" alt="访问军营" loading="lazy"></p><p>访问军营</p><p><img src="'+x+'" alt="访问农村" loading="lazy"></p><p>访问农村这是我在2003年说过的一句话。这不是突发之想，而是从很早以前就有的想法。在担任首尔市长之前，我在企业做过很长时间的CEO，有过多次访问世界一流城市的机会。在接触、了解这些城市的行政、交通、福利、文化的同时，我也感触到了各个城市在提升品牌形象方面的努力，由此我便想到，首尔也应当制定符合我们这个城市特性的品牌战略。</p><p>起一个好的名字是品牌战略的一环，因为名字可以体现形象和价值。民选三期市政府设立的“城市绿化局”、“健康城市促进班”、“城市设计科”等部门，一看名字就知道工作内容和性质，还能给人一种亲切感。</p><p>“清溪广场”是在市民广泛参与的基础上最终确定的名字。我们在3700多位市民建议的名字中选择了最上口、最容易记住的“清溪广场”。征名活动拉近了市民与工程之间的距离，给人以一种更亲切、更贴近的感觉。</p><p>品牌名称战略中，最引人注目的就是变更城市的中国语标记。</p><p>2005年1月，我们宣布把我们这座城市的中文名称从“汉城”改为“首尔”，取“首屈一指的城市”之意。</p><p>其实，变更首尔的中文标记，这已经不是第一次了。公告处在10多年前就开始试行，但考虑到各方面因素，一直保留着“汉城”这个名字。</p><p>从现实生活考虑，“汉城”这个名字也大有更改的必要。有时候，中国人在首尔就会因为名字的关系遇到诸多不便，比如汉城（国立Seoul)大学和汉城（私立汉城）大学就很容易混淆。站在提升城市品牌形象的立场上看，更改“汉城”这个名字也很有必要。但是，和10多年前一样，方案提出后就听到了担忧的声音。</p><p>“中央政府想做但没有做成，首尔以前经过多次讨论，最终也不得不作罢。现在又要提出这么做，能行吗？”</p><p><img src="'+A+'" alt="与谢赫·穆罕默德在一起" loading="lazy"></p><p>与谢赫·穆罕默德在一起中文名称变更工作在一开始的几个月间只是从这个科推到那个科，从行政科，到国际合作科，到文化科，最后到了文物科。文物科为此设立了由中国语教授、中国事务领域记者、当地中国人组成的咨询委员会。</p><p>“汉城这个名字是怎么来的？是过去给中国进贡的附属国首都的名字。从一定意义上来说，带有轻蔑的意思。现在我们的城市正在为跻身世界一流城市之林而努力，更改名字是一个时代性课题。”</p><p>我再次向咨询委员会强调更名的重要性。我没有催促尽快实行，而是希望充分收集意见。咨询委员会召开了研讨会，广泛收集市民们的意见，公开征集新的城市名称就用了一年多时间。征集活动是通过网络进行的，也有意征求了中国人的意见。在征集到的名称中，经过咨询委员会审核，最终选择了“首尔”。</p><p>2005年1月19日，我正式宣布把“汉城”的中文名称改为“首尔”，但立即遭到中央政府的反对。</p><p>“‘首尔’这个词以前根本就没有，也违反了韩语的习惯。”</p><p>“街道上的指示牌怎么办？把那些牌子都换掉得花多少时间？”</p><p>“这么做会不会刺激到中国？改名字可不是那么简单的事情！”</p><p>文化观光部、外交通商部最初都站在反对立场。首尔市已经发表了更名公告，因为中央政府的反对，一度面临加重混乱的危机。</p><p>市政厅的文物科长决定直接去面见政策室的负责人。</p><p>“如果说早晚要变更，现在是最好的时机。”</p><p>政策室的负责人表示了支持，但外交通商部还是以需要更换标记的预算和时间为理由提出反对。</p><p>“据我们掌握的情况来看，需要更换的标记并不是很多，从机场到市中心的机场路上只有10多个有中文标识的标牌，先更换这一部分，然后变更一部分交通地图就可以了。”</p><p>文物科长直接反驳了外交通商部的理论，在国务总理室与有关负责人进行协商后，最终获得了认可从确定新名称到获得中央政府同意，一共花费了大约两个月时间。2005年3月初我去国外访问的时候，机场路上的中文标识还是“汉城”；等我回来的时候，已经变成了“首尔”。一开始持反对意见的外交通商部也终于改变了想法，向中国递交了正式外交书函。</p><p>给予我们最多帮助的反而是民间领域的中国人。和中央政府一部分部门的担心不同，他们很快接受了这种变化，因为新的名称给予了他们更多方便。接下来就要看中国政府的立场了。</p><p>“中国人是讲究实用性的。如果用‘汉城’这个标记，不方便的反而是中国那边。改成‘首尔’之后，韩国人和中国人的交流会更加方便，所以中国政府也一定会接受的。”</p><p>“如果中国政府不接受，该怎么办？”</p><p>有关负责人表示了担心。</p><p>10月24日，中国政府对外宣布，中国将启用韩国首都汉城市的中文新译名“首尔”。而在两个多月前，中国国家主席胡锦涛在发给卢武铉总统的8月15日光复60周年贺函上就已经使用了“首尔”这个名称。</p><p>“首尔”不仅仅是一个单纯的名字，它将成为一个影响广泛的固有品牌。在顺利完成更名工作之后，文物科连续两个月拿到了成果奖金，他们完全有这个资格，因为他们完成了一项艰难而重要的任务。</p><p>城市品牌营销是一项全方位的工程，需要做的工作还有很多。每年五月举办的“首尔文化节”（Hi Seoul Festival）也是一项颇受关注的活动，我们的计划是把“首尔文化节”发展为像巴西的“桑巴庆典”、日本的“札幌文化节”、德国的“十月节”一样具有世界影响力的城市庆典。</p><p>首尔的品牌化工作仍在进行中，这和提高城市福利水平、发展文化传统、改善城市环境等工作有着不可分割的联系。要想让包装更加夺目，最重要的是要有厚实的内容。</p><p>21世纪的城市品牌价值，不仅在于功能和效率，还在于环境和文化。复原清溪川、构建首尔林、改善大众交通等一系列项目都是提升城市品牌价值的有效手段。</p><p>品牌价值高的城市，就是“人们乐于前往的城市、乐于生活的城市”。为了这样一个目标，首尔一直在前进。</p><h2 id="三、可持续发展—开发与环境一举两得" tabindex="-1">三、可持续发展—开发与环境一举两得 <a class="header-anchor" href="#三、可持续发展—开发与环境一举两得" aria-label="Permalink to &quot;三、可持续发展—开发与环境一举两得&quot;">​</a></h2><h2 id="从清溪川找到的城市竞争力" tabindex="-1">从清溪川找到的城市竞争力 <a class="header-anchor" href="#从清溪川找到的城市竞争力" aria-label="Permalink to &quot;从清溪川找到的城市竞争力&quot;">​</a></h2><p>“有批评说，市长只看重眼前的开发和项目成果。您对此怎么看？”</p><p>在2006年的一次座谈会上，某学报社的总编辑提出了这样一个问题。</p><p>“说我只关心开发的人，我想他应该没有真正理解开发的概念。复原清溪川绝对不是一个单纯的开发项目，我们应该从复原环境的视角全面地看待它。”</p><p>我不能接受“只关心开发”的批评。如果对清溪川置之不理，若干年后会出现什么样的状况呢？</p><p>22万商人冒着被有毒气体侵害的危险，在清溪川附近谋生。清溪川的地下空间，几十年来阳光无法照射进去，变成了污水和恶臭充溢的巨大下水口。存在于市中心的这个脏乱地区给访问首尔的外国人留下了不好的印象。这一切都和“建设世界一流城市”的目标显得如此不协调。</p><p>经过彻底整治，如今的清溪川又是怎样一番面貌呢？</p><p>曾经只有老鼠和野猫的清溪川，现在有鱼儿在游动了。水路开通后，鲤鱼最先来访，然后是巴鸭、红隼、斑嘴鸭……只在一级水质的水域边生活的珍贵客人——翠鸟也来了。复原不到一年，清溪川下游区就重新成为了候鸟的栖息地。</p><p>生活在清溪川周边的市民们的生活也在不知不觉中改变了。孩子们可以卷起裤腿，到清溪川里抓泥鳅了；妇女们可以提着篮子，到清溪川边采野菜了。到了夏天，人们还可以把脚泡在凉凉的河水里，三三五五聊聊家常。碧绿的河水流向钢筋水泥的丛林，召唤越来越多的人来到这里，暂时摆脱疲惫的生活，寻找心灵的闲暇。</p><p>灰色的城市中心诞生了人与自然和谐共存的环境。清溪川变成了都市人真正需要、由衷喜爱的休闲空间。</p><p>在外国人眼里，清溪川也成了名副其实的首尔名胜。事实上，在复原清溪川工程尚未完全竣工时，威尼斯建筑双年展就授予了我们“最佳执行奖”。各国专家对复原清溪川工程表示了极大关注，对这条流经5.8公里的城市河川毫不吝惜赞美之辞。</p><p>意大利的电视台、广播电台，英国BBC电视台等欧洲媒体都对我们的复原清溪川工程进行了大篇幅的报道。其实，他们最关心的就是首尔人在复原清溪川的过程中是如何兼顾开发与环境、使两者相辅相成的。</p><p>城市开发不是破坏环境，而是可以拯救环境。复原清溪川工程展示了开发与环境并存的可能性。</p><h2 id="开发和环境不冲突" tabindex="-1">“开发和环境不冲突” <a class="header-anchor" href="#开发和环境不冲突" aria-label="Permalink to &quot;“开发和环境不冲突”&quot;">​</a></h2><p>我就任市长后，一直被许多人称为“新开发论者”。这个称呼和“推土机”的外号一样，都是我不太能接受的评价。</p><p>有人批评说，我把整个首尔变成了一个施工工地，而且为了在任期内展示成果，无理地强行施工，由此引起了诸多副作用。</p><p>说实话，如果真是那样，我就不会把清溪川打造成现在的样子。也许把那一带全部填埋，建成大型的娱乐设施和商业设施，所谓的“成果展示”会更加辉煌吧。</p><p>我知道在批评者中，有人认为应该像保护自然环境一样，无条件地保护城市环境，杜绝一切人工开发。但是，我理解的“城市开发”和他们不太一样。所谓改善城市环境，应该首先考虑生活在城市里的人。因此，城市开发和圈起一片土地而建立国家公园是不一样的。</p><p>城市开发的目标应该是让市民的经济生活、文化生活、福利生活更加丰富、更加人性化。环境和开发一举两得是完全有可能的。</p><p>构建首尔林项目也是一个很能说明问题的例子。如果我一味注重开发项目的经济价值，首尔林就不会是现在这样有树木林阴、野兔奔跑的生态公园。</p><p>事实上，圣水洞一带很长时间以来一直被许多开发商所看好。广津区、圣水洞、东大门相连的一带是首尔市内相对落后的地区。以前的“中国城”、“商业区”、“棒球场”等大规模开发计划都是基于其开发前景、看好其经济价值而制定的。但是，我的视角有所不同。</p><p>“现在的开发方式应该和过去有所不同。首尔东北部地区之所以发展缓慢，最大的原因在于那里缺少亲环境性的基础设施。如果多建设一些亲环境性的基础设施，周边地区的居住环境就会有很大改善，自然开发也就变得可行了。”</p><p>为什么要在圣水洞构建首尔林？江南区有奥林匹克公园，江西北区有世界杯公园，江西南区有老鹰公园，但是东北区有什么呢？那里的环境基础设施特别薄弱。我们的想法就是先建设东北区的环境基础设施，然后再自然开发周边地区。</p><p>事实上，首尔市的环境基础设施依然有所不足。为了更好地改善市民生活，政府应该增加更多亲环境性的空间。只有这样才能更快跻身世界一流城市之林。</p><p>我曾经说过，要把龙山美军基地一带改造成市民公园。这种想法至今没有改变。如果只考虑龙山美军基地一带的经济价值，这片土地可谓寸土寸金。但与其经济价值相比，我更看重它的历史象征性。如果在这个地方建一座所有人共享的市民公园，将是多么有意义的事情。那应该是一座可与美国纽约中央公园相媲美的城市中心绿地公园。</p><p>这样的环境基础设施一定会提高首尔的知名度，加大对外国投资者的吸引力。因此，这样的开发项目不仅有助于拯救环境，也会在拯救经济方面起到很大的作用。</p><p>以前，人们习惯于把环境和开发看做两个对立的概念：为了保护环境就要阻止开发，开发的结果只可能是破坏环境。但现在，这种对立意识渐渐被抛弃了。开发和环境可以是相辅相成的概念。</p><p>1992年6月在巴西里约热内卢举行的联合国环境与发展大会通过了《21世纪议程》，提出“可持续发展”的理念。所谓可持续发展的核心就是：“既满足当代人的需要，又不对后代人满足其需要的能力构成危害。”</p><p>不可否认的是，在20世纪90年代之前，韩国的开发政策是有一定盲目性的；但在当时，我们也不可能过多考虑环境、文化等因素，这也许可以说是时代的局限性。</p><p>我也经历了那样的时代，而且不可否认的是，我也曾经是那种盲目开发工程的领头者。在当时，我们都不认为这有什么错，即使为了生活也应该多做开发，那是大多数国民达成的共识。</p><p>但是现在，我们身处的社会已经发生巨大的变化。以前的开发理念、开发方式就像以前的流行时装一样，已经不再符合这个时代的要求。现在是注重环境和文化的时代，城市开发应该寻找与之相符的新目标。如果一味、绝对地否定开发，就不会有“可持续发展”的概念。“可持续发展”是以开发为前提的。为了更好地保护、管理环境，也需要我们做一些翻新、修改工作。</p><p>不是生硬的非此即彼，而是两者兼顾、一举两得。只有相辅相成才是符合新时代要求的范例。</p><h2 id="四、行政韩流——出口秘诀" tabindex="-1">四、行政韩流——出口秘诀 <a class="header-anchor" href="#四、行政韩流——出口秘诀" aria-label="Permalink to &quot;四、行政韩流——出口秘诀&quot;">​</a></h2><h2 id="出口到世界的首尔行政系统" tabindex="-1">出口到世界的首尔行政系统 <a class="header-anchor" href="#出口到世界的首尔行政系统" aria-label="Permalink to &quot;出口到世界的首尔行政系统&quot;">​</a></h2><p>“像首尔的汉江一样，我们也想开发河内的红河，请李明博市长多多帮助。如果首尔能协助我们策划开发计划的话，项目进行时我们会让韩国企业参与。”</p><p>越南河内市市长在访问首尔时曾经这样拜托我。河内市长是一个充满热情、有进取想法的市长，特别关注城市现代化建设。</p><p>他曾经多次访问首尔，每次都对首尔的电子政府系统表示出极大关注。</p><p>随同河内市长一起访问首尔的河内公务员们也对首尔的电子政府系统表现出极大兴趣，并且向首尔的公务员们咨询了许多相关问题。在那之后，首尔的电子政府系统便十分自然地走上了输往越南河内出口之路。我访问河内也是为了商议“电子政府谅解备忘录合同”事宜。</p><p>红河开发项目原先并不在我们计划之中，但河内市长表现出了很大的诚意。因为他们不具备大规模建设经验，红河开发的负担自然不轻。</p><p>通过一系列的协商，首尔不仅参与了河内市电子政府建设工程，还参与了红河的开发工程。在确定了红河开发长期计划之后，我们的企业就可以正式向河内进发了。</p><p>蒙古的乌兰巴托是首尔的姐妹城市。乌兰巴托政府也在积极借鉴首尔电子政府系统。这件事还要追溯到2006年5月。“首尔文化节”期间设立了“乌兰巴托日”，蒙古的艺术团体在首尔进行了演出，我还向乌兰巴托市长授予了“名誉市民”称号。在随后的媒体采访中，有一位记者问乌兰巴托市长：</p><p>“乌兰巴托和首尔进行合作的话，会从哪方面开始呢？”</p><p>他毫不犹豫地回答道：</p><p>“我们想学习首尔的电子政府系统，关于这一点我想和李明博市长另行讨论⋯…”</p><p>就这样，首尔和乌兰巴托开始了促进电子政府系统合作项目。</p><p>在离开韩国前，乌兰巴托市长和我进行了详谈。</p><p>“我们乌兰巴托市的资金并不充裕，所以，具体从哪个领域开始，我想听听您的建议。最重要是，希望您能来看看我们城市的环境。所以，我们会尽快邀请您。”</p><p>乌兰巴托市长非常热情，但正如他所说的，他们的政府资金并不充裕，构建电子政府的通信基础设施也很落后。但他之所以提出要建立电子政府系统，是有其特殊理由的。这个特殊理由不是其他，正是为了铲除腐败。据说在乌兰巴托，办公厅腐败现象很严重，连发放土地证也要索取小费。正是为了消除这种不正之风，乌兰巴托市长决心构建一套电子政府系统。</p><p>但是，乌兰巴托是一座草原城市，稍微走出市中心，就会看到许多城市贫民居住的帐篷。在这样的地方构建一个类似首尔通信环境是不可能的。但是，首尔还是决定向姐妹城市乌兰巴托伸出援助之手。这么做不是出于眼前利益，而是着眼于未来投资。</p><p>2006年9月，在乌兰巴托的“首尔日”活动中，电子政府体验馆正式开放，市民们可以在馆内体验到公文查询、发行等模拟办公环节。据说乌兰巴托的市民们表现出浓厚的兴趣，体验馆一连几天都是满员接待。活动结束后，我们向乌兰巴托市捐赠了计算机等全套装备。</p><p>现在，河内市长已经升任越南财务部长，乌兰巴托市长也已升任蒙古国务总理。我相信，首尔展现出的友好态度在今后将带来更多合作机会。</p><p>首尔的电子政府系统最先出口的城市是莫斯科。在首尔曾经举办“莫斯科日”活动中，当时的莫斯科市长和莫斯科文化艺术团一起访问了首尔。</p><p>“我们正在制定‘e-莫斯科&#39;电子政府促进计划。听说首尔电子政府系统运行得很成功，我们想向你们取取经。”</p><p>听到莫斯科市长的这番话，我友好地表示，首尔愿意为莫斯科提供帮助。</p><p>2004年6月，我和国内几位企业家一起访问了莫斯科，准备趁热打铁，促进电子政府系统的出口计划。莫斯科市内一片热烈气氛，相关人员更是围着我们，从早到晚像开听证会一般，仔细询问有关首尔电子政府系统的各种问题。</p><p>“如果首尔把全套的电子政府系统出口给我们，我们将不通过另外的招标，直接让韩国企业参与莫斯科市的电子政府系统建设。”</p><p>有一天，莫斯科市长把他的打算直接向我说明。我很快在头脑里算了一笔账：</p><p>“那样的话，对我们的企业来说，就是打开了通往莫斯科市场的一条通路，而且首尔市在项目费中还有咨询费和知识产权费股份，可以用这部分费用设立IT领域的奖学基金。”</p><p>如果合作达成，首尔和莫斯科将取得双赢的成果。我向莫斯科市长表示了赞成的意思：</p><p>“如果直接让韩国企业参与，对莫斯科来说，就可以避免实施误差：对韩国的企业来说，也是一个大好机会。”</p><p>给那年的11月，莫斯科市举行了“首尔日”活动。在活动期间，我们和莫斯科市就电子政府系统合作建设签署了“谅解备忘录合同”，一方面首尔市积极协助莫斯科市电子政府系统建设，另一方面向莫斯科出口电子政府系统模式，韩国企业参与具体建设。</p><p>“e-莫斯科”是一个计划耗时5年、投资620亿卢布（约为韩币2兆）的大项目。现在参与这个项目的韩国企业有三星SDS、LG、KT、三星物产等大企业。但我们能感觉到，经过初期的磨合之后，中小型企业也将在那里找到自己的市场。</p><p>在全球化背景下，经济活动没有国界，全世界统合成了一个大市场，竞争也日益激烈。在这样的情况下，政府机构应当为个人、企业提高竞争力提供有力的支持。但是，韩国的政府机构在这方面做得并不好，有时候甚至会成为企业提高竞争力的阻碍。</p><p>有一次我就听到了一位企业人士的抱怨：</p><p>在一次由世界经济论坛主持的有关韩国吸引投资的会议上，因为韩方人员的问题，差一点引起了乱子。这次会议邀请了各国政界、经济界的重要人士，其规格和重要性可想而知。但是，各国外宾只到了10多人。一听“乱子”的内容更是让人生气：</p><p>“政府代表应该坐在上席。”</p><p>“这是什么话？会议的内容不是吸引投资吗？”</p><p>“但那是以政府名义举行的，难道让政府代表坐在后边的座位上吗？”</p><p>“到底是来这儿做什么？”</p><p>所以，乱子的内容就是“政界代表和经济界代表应该坐在什么位置”的问题。据说，“致辞应该由一个人还是两个人”的问题也引起了一片争论。在这过程里没有积极地推进引资活动。</p><p>事实上，这样的事情并不少见。到国外吸引投资的企业人士由于不能进行重要的引资活动，更多的是由政府高层官员出面协助。</p><p>一些先进国家的情况和我们大为不同。他们在开会之前就会制定出详细的计划，协商时就集中在必须达到的目标上。像之前我提到过的“莫斯科之行”，相关人员的提问几乎达到了“听证会”</p><p>水平。他们的目标意识非常强，政府和公共机关对企业和国民起到了很大的支持作用。</p><p>现在，韩国的政府和官员们也应该有这样的意识了。既然首尔市的电子政府系统可以出口到越南、俄罗斯、蒙古，可见政府也能成为营销的对象。</p><p>在我上任首尔市长初期，市政府一共有30多个电算室，各局、各科都有两三个网页，整个市政府系统光网页就有92个，这样的状态只会加重市民的混乱。</p><p>“给你两周时间，看看完善整个系统的第一步怎么走。”</p><p>我向大学教授出身的信息化企划团长下达了指示。两周后，信息化企划团长向我报告说：</p><p>“最紧急的是统一各个系统，把它们连接起来。但如果要把全部都统一起来的话，需要很多时间。可以先统一一部分，操作起来方便一些。”</p><p>“要么不做，要么就一次性做好！”</p><p>我之所以这么强硬地要求一步到位，是因为接到报告说，统一系统时各部门之间的冲突也不小。与其拖拖拉拉、顾此失彼，不如一鼓作气，打一场硬仗。</p><p>我指示另行成立信息系统整合促进会，由各个室长、局长、经营策划室长组成，协助信息化企划团长开展工作。</p><p>从2003年春天开始的信息系统整合工作，到6月末就完成了，电子政府系统的基础就是从那时候建立起来的。信息系统的整合有两大优点。</p><p>首先是大大减少了运营成本。以前的30多个电算室重复工作很多，系统整合之后可以避免不必要的浪费。另外，工作效率的提高也是立竿见影。比如，在系统分散的时候，下达一个人事变动通知就需要各个系统分别输入数据，经过整合之后，只要输入一次就可以传达到各个部分。</p><p>当然，获益最多的还是市民。像以前那样，要想拿到一个证明书，光找网页就得花不少时间，看看每个科的网页上似乎都有涉及，究竟到哪里办理反而摘不清楚了。系统整合之后，只需点击一次市民服务就可以了。</p><p>上下水管、电力、通信、天然气、暖气等地下铺设管道的情况也可以在线掌握了。以前，施工人员需要直接挖开地面才能知道什么地方埋了什么管道，但现在，我们把各个公司的管道铺设地图做成了数据库，实现了信息在线共享。</p><p>首尔市的电子政府系统在联合国和美国行政学会支持的100大城市电子政府系统评比中，2003年、2004年接连两次名列第一。</p><p>这也在一定程度上帮助了首尔的电子政府系统扬名于世界。</p><h2 id="值钱的行政、挣钱的行政" tabindex="-1">值钱的行政、挣钱的行政 <a class="header-anchor" href="#值钱的行政、挣钱的行政" aria-label="Permalink to &quot;值钱的行政、挣钱的行政&quot;">​</a></h2><p>首尔的交通系统也多受称赞，在其他国家刮起了“行政韩流”。</p><p>回想起最初改革公共交通时经历的困难，真可谓百感交集，成就感也油然而生。</p><p>2004年7月，大刀阔斧的公共交通改革引发了猛烈的舆论炮火。改革初期的一些失误引起了一定程度的交通混乱。整座城市仿佛变成了战场，公务员们日夜战斗，但批评声丝毫没有减弱。</p><p>“还原公交系统！”</p><p>“李明博市长下台！”</p><p>在这样的口号此起彼伏时，支持的声音却在意想不到的地方出现了。国外许多城市对首尔的公共交通改革表示一致关注。</p><p>首先是越南建设交通部长官一行访问了首尔，在参观巴士管理系统（BMS）时，他们惊叹的表情令我印象深刻。回国前，他们向首尔提出了包括停车政策在内的交通政策全部的技术性支援请求。</p><p>这样的肯定也使我们增强了对首尔交通改革政策正确性的信心。</p><p>将举办2008年奥运会的北京也派来了大规模访问团。香港交通局也冲着巴士管理系统等信息访问了首尔。英国下院交通委员会的六名议员也到首尔来学习交通政策，他们是为申请2012年伦敦奥运会、制定解决伦敦交通问题方案，远道赶来寻求帮助的。</p><p>土耳其的伊斯坦布尔虽然邻近众多欧洲大城市，但他们也对首尔的交通政策十分关注。伊斯坦布尔市长和我畅谈了30分钟，听我谈到首尔的交通系统情况后，他很快决定到首尔进行为期3天的正式访问。</p><p>除此之外，日本、印度尼西亚、菲律宾等国家也都有意借鉴首尔的交通系统。国外的媒体报道很热烈，以德国记者为首，印度、中国、菲律宾、印度尼西亚等国的记者团先后来到首尔，对逐步走上正轨的首尔公共交通改革进行了深入报道。</p><p>2004年10月，国际公共交通联盟（UIPT）主办的学术研讨会在澳大利亚举行，首尔的公共交通改革成果是这次研讨会的重点课题。以美国和中国为首的世界各国大学研究团体也积极向我们索要相关研究资料。</p><p>这时候，国内民众也开始重新审视这场经历波折的交通改革了。</p><p>“了解之后才知道是很了不起的。”</p><p>据说市民之间也在流传这样的话。</p><p>当时参与公共交通改革的一名市政研究员现在一周内平均要接待两次外国客人的访问，其中大部分是有意借鉴首尔先进的交通系统的国外交通专家。据说，他们对首尔的交通政策以及与IT技术相结合的独特系统赞叹不已。</p><p>“由于公共交通改革，我都成了世界性的交通政策专家了。”</p><p>这位研究员兴奋地跟我开起了玩笑。</p><p>如今，首尔的交通系统已经成为世界一流“商品”。在交通系统行政秘诀向外出口之后，紧接着便是韩国企业的装备和施工人才向外出口了。</p><p>行政系统的出口改变了以前的官僚组织的形象。以前的偏见是：公务员只知道花国民的税金。以首尔行政系统出口为契机，这种偏见慢慢消失了。</p><p>有学者指出，未来世界最具增值潜力的是知识、信息和文化相关产业。从这个意义上来说，行政服务是一种具有无穷潜力的商品。</p><h2 id="五、平衡发展——南北一同前进" tabindex="-1">五、平衡发展——南北一同前进 <a class="header-anchor" href="#五、平衡发展——南北一同前进" aria-label="Permalink to &quot;五、平衡发展——南北一同前进&quot;">​</a></h2><h2 id="促进新城市开发的理由" tabindex="-1">促进新城市开发的理由 <a class="header-anchor" href="#促进新城市开发的理由" aria-label="Permalink to &quot;促进新城市开发的理由&quot;">​</a></h2><p>“我认为开发新城市是典型的善心公约。开发的难度先不说，恐怕对房地产价格波动也会产生不好的影响。”</p><p>这是反对新城市开发的一位专家的意见。类似这样的意见都是因为对新城市开发的信息不足、认识不准确而形成的。</p><p>“担心开发难的问题，一句话：杞人忧天。新城市开发不是让原来生活在那里的人离开，而是让他们在更便利、更优美的环境中生活。”</p><p>事实就是这样。新城市开发不是为了赶走那里的居民，而是要让他们生活得更好，对租赁的住户也能实行保障。</p><p>我之所以如此关注新城市开发，和我年轻时辗转于贫民区的经历有关。高中毕业后来到首尔，我就住在孔德洞、孝昌洞一带的贫民街上。那时候，父母在首尔租的房子特别窄小，怎么也容不下我和妹妹两个人睡觉。于是，我一个人随身只带着一个勺子就走出家门，在孔德洞、孝昌洞一带找了间屋子住下。房租是按天数计算的，当然也不可能是单人间，很多人随随便便挤在一间屋子里，能有个地方睡觉就不错了。人虽然多，厕所却只有一个，上厕所就和中彩票一样难，于是难免有人随地大小便，屋子里里外外从早到晚都是臭烘烘的。越是没钱的人，住的楼层就越高，因为楼上离厕所远，屋子也窄小，价格自然比楼下的还要便宜一些。</p><p>那时候，我经常就住在顶层。虽然如此，能有一个地方安身我已经觉得很幸运了。</p><p>一直到1964年，我二哥签下合同，搬进东大门的国民租赁住宅，我们全家的居住环境才算有了改善。那套房子和我住的出租屋相比简直犹如宫殿，但事实上，那也还是在贫民区。</p><p>2002年竞选市长的时候，我又一次回到了那个地方。让我大吃一惊的是，那一带生活区和1964年时候几乎没什么变化。虽然道路重新铺过了，有的地方也盖起了新房子，但总体而言还是老样子。</p><p>“怎么会这样呢？怪不得江北的居民对生活环境多有抱怨…•••”</p><p>新城市开发想法就是在那时候产生的。</p><p>就任市长后，我从原先住的论岘洞搬到了市长公馆。论岘洞家是我在现代建设公司任职时，郑周永会长为了便于我接见外国企业代表而专门建造的。既然说要开发江北，我当然应该以身作则搬到江北。只有彻底融人这个环境，才能真正了解这里的情况。</p><p>在搬到市长公馆后不久，一位报社的记者曾经这样问我：</p><p>“市长，您了解江北人的挫折感吗？”</p><p>当时我刚刚发表了首尔市要开发恩平区、城北区吉音洞、城东区往十里等三个新城的计划。</p><p>事实上，江北地区迟迟不开发是有其原因的。江北贫民区的国有土地、市属土地占了很大一部分。对于条件不太好居民来说，自行开发的难度可想而知。据说，住在江北的人要想再开发话平均需要13年，最快也要7年。很多居民在等待了几年之后，不得不怅然地选择离开生活多年的地方。</p><p>如果市政府不直接出面进行开发，或许再过几十年，江北地区也不会有太大的起色。事实上，以前陆陆续续由民间房地产开发企业进行再开发项目都是在一些落后的地区建造新的公寓。结果，原先那里的居民没有条件搬进新公寓，只能辗转到其他的贫民区，形成恶性循环。而且，由于这些开发项目的规模都比较小，民间企业很难构建道路、学校、公园等生活基础设施。</p><p>我们可以以一个拥有独立住宅的江北市民为例，说明一下当时的情况：</p><p>住在江北的甲先生，因为自家房子又旧又窄，决定拆掉老房，盖一座新房。既然要盖新房，干脆再往上加一层。新房盖好后又住进两户人家。所以，原先一户变成了三户。甲先生虽然很高兴，但奇怪的是，房价没有往上涨。住的人变多了，可是路还是那条路，停车的空间变得更加拥挤了，有路段几乎变成了停车场。</p><p>像这样的恶性循环只能导致江北的生活环境越来越糟糕。</p><p>新城市开发的目标就是要把这样的恶性循环画上一个圆满的句号。具体的构想是确定一个大的区域，作为平衡发展的促进地区，首尔市先投资修路、栽植绿地，然后建造学校、公园等文化基础设施。新城市的开发需要政府和民间企业携手并进。基础设施由公共部门负责建设，公寓和商业设施则由民间企业进行开发。</p><p>“政府促进板桥、华城、金浦、坡州等四个新城市建设能使大约14万户居民受益，而新城市开发项目能使86万户居民受益。”</p><p>这是根据市政研究院的研究资料统计出来的数字。</p><p>江北的新城市开发项目虽然是由首尔市政府主导的，但地区居民也积极参与了整个策划过程。而且，我们还根据每个区域的特性制定了相应的开发计划。可以说，地区居民是新城市开发最大的受惠者。</p><h2 id="现在是-1对1-的开发时代" tabindex="-1">现在是“1对1”的开发时代 <a class="header-anchor" href="#现在是-1对1-的开发时代" aria-label="Permalink to &quot;现在是“1对1”的开发时代&quot;">​</a></h2><p>再好的政策也满足不了所有人的需求，所以，大部分政策出台之后，都会有赞成和反对的意见。公共政策应当朝着满足大多数人需求方向发展，对于无法满足的少数人，则要尽力说服他们。</p><p>这时候，最好办法就是针对个人或集团的特性，制定“CasebyCase”的解决方案。情况越是复杂，“CasebyCase”的方案就越能起到良好的作用。</p><p>新城市开发政策公布之后，也是立刻就听到了欢迎和批评两种声音。这个计划是我在民选三期市长竞选时提出12个公约中的一个。出任市长后，我立即设立了“地区均衡发展促进团”，后来改名为“新城市项目总部”。</p><p>新城市开发项目于2002年10月选定了恩平、往十里、吉音为示范地区，第二年11月又选定了峤南、汉南、典农、弥阿、新亭等12个地区为2期新城市开发地区。除了这15个地区以外，后来又接受了增加的10个地区的申请，预计到2012年全面建成。</p><p>在新城市开发计划公布之后，给予我们最大支持的还是地区居民。根据首尔市自行实施的民意调查，70%以上的市民表示支持，85%的市民赞成把新城市开发扩大到全市范围。</p><p>但是，获得市民支持过程并不轻松。在往十里新城开发初期，由于居民强烈反对，9个月内开了40多次专家会议、20多次居民座谈会和5次公开说明会。像这样的市民参与决策的先例，也是新城市开发项目中值得关注的地方。</p><p>由于各个地区的环境、民意各有不同，整个工程分为“新城开发型”、“城市中心（DownTown）型”、“居住中心型”三种不同的形式进行开发。在具体实施过程中，也最大程度地考虑到地区居民的要求。</p><p>在以“新城开发型”为定位的恩平新城，最初设定地区居民的土地补偿价格时，就尽量消除了对他们的不利因素。而且，针对原来居民重新入住制定了多种优惠政策。比如，适当降低住宅销售价格，对于入住金不足的住户，还调整了长期低息贷款方案，尽量减轻居民的负担。另外，在居民入住之后，也对他们生活进行一定的扶助。比如，为原先从事花卉业居民提供一定机会，让他们可以继续从事以前的生意。在税收方面，也实行一定的减免政策。</p><p>在以“居住中心型”为定位的吉音新城，为了维持以前的公共服务，建造了上层住宅、底层商铺的复合型路边商店。在构建公共设施的过程中，也照顾到了各个社区的平衡。</p><p>以“城市中心型”为定位的往十里新城是从朝鲜时代起就一砖一瓦发展起来老城区，居住人口密度很大，有很多都是几世同堂的大家庭。因此，在开发过程中尤其关注社区的亲环境性，加大基础设施方面的建设，努力使居民生活和商业一起发展。</p><h2 id="六、协作——众人拾柴火焰高" tabindex="-1">六、协作——众人拾柴火焰高 <a class="header-anchor" href="#六、协作——众人拾柴火焰高" aria-label="Permalink to &quot;六、协作——众人拾柴火焰高&quot;">​</a></h2><h2 id="市民和企业的参与" tabindex="-1">市民和企业的参与 <a class="header-anchor" href="#市民和企业的参与" aria-label="Permalink to &quot;市民和企业的参与&quot;">​</a></h2><p>“巍峨的北汉山，壮阔的汉江，清澈的清溪川，希望我们的首尔越来越美丽。”</p><p>“从未有过的幸福⋯⋯”</p><p>“某某和某某，在清溪川畔，相亲相爱地生活。”</p><p>这些都是印刻在清溪川“希望之墙”上的文字。</p><p>“希望之墙”用富有亲切感的文字和有趣的图画展现了首尔两万多市民美好愿望。更令人感动的是，我们还在“希望之墙”上读到了在韩国居住的外国人以及海外同胞们心声。</p><p>愿意参与“希望之墙”活动的市民只需交2万韩元，就可以把自己的希望图画或文字印刻在1300摄氏度条件下烤出来的瓷片上，成为整体壁画的一部分。“希望之墙”位于黄鹤桥和五间水桥两旁，长50米，高2米，对整个清溪川来说不过是很短的一小段，但现在，“希望之墙”已经成为清溪川观光的必看景点。</p><p>“希望之墙”之所以采用这样的运作方式，不单纯是为了节约预算，更是为了吸引市民们直接参与复原清溪川的历史性项目。让我们感到欣慰的是，市民们也把这看做一次珍贵的机会，热情地做出了回应。</p><p>“老百姓这么积极、自发地参与政府部门的项目，还真是不常见呐。”</p><p>市政厅一位官员在回顾这次活动时这样说到。</p><p>在复原清溪川过程中，市民们的参与还不止于此。很多市民通过购买5000韩元一块的文化砖，为复原工程作出了自己的贡献。</p><p>市民们的参与也使复原清溪川的意义变得更加深远。</p><p>除了市民个人的捐助以外，民间企业的赞助也络绎不绝。随着清溪川高架桥的消失，一部分建筑扩大了视野，这在以前是难以想象的。到过清溪川的游客们都会对企业鲜明的标志留有印象，这样的户外广告价值空间极大。企业十分清楚这一点，欣然通过各种赞助活动参与了复原清溪川工程。</p><p>清溪川上的22座桥梁中，三一桥是友利银行全额赞助修建的；</p><p>GS建设公司赞助了五间水桥周围“希望之墙”修建费用，新韩银行也资助了一座桥的拱形维修工程，朝兴银行承担了一幅壁画的制作费用……企业参与复原清溪川工程具有超越经济性效果意义。一方面是参与历史复原的珍贵机会，另一方面也看到了和政府公共部门进行协作可能性与效果。</p><p>首尔广场的建设工程也积极利用了企业赞助。</p><p>首尔广场酒店（PLAZA HOTEL）是修建首尔广场的最大受惠者之一。作为首尔的象征，首尔广场每天都会吸引成千上万的市民和游客。从首尔广场的绿地向南望，就能看到首尔广场酒店的华丽身姿，其广告效果可想而知。据说，首尔广场酒店中能俯视广场景观的房间价格也上涨了。受益颇多首尔广场酒店随即表示出捐款的意愿。广场喷泉工程就是在他们的资助下完成的。以修建广场为契机，市政厅墙面上的大型圆形钟也是在瑞士驻韩大使的主持下，由首尔商工会议所和瑞士Swatch集团韩国分公司共同捐赠的。</p><p>我还指示在户外广告集中的地方放上城市品牌广告。</p><p>“在市政中引入企业意识不是指光顾着挣钱，而是要充分宣传城市形象，使政府和市民的沟通更加顺畅，更加贴近市民，获得情感上共鸣。”</p><p>这是我在某次会议上强调的话。渐渐地，公务员们对于城市形象宣传、公益广告发布表现出了更积极的姿态。</p><p>城市品牌广告最合适的载体是公共汽车。公交车身广告就是移动的首尔市宣传大使。我们从改善公共交通初期就开始积极利用这个宣传平台。</p><p>第一个引人公益广告是“热爱首尔”活动。这次活动的宗旨是提高市民的城市自豪感，在城市生活中注人新的活力。红色心形代表首尔市民热烈的爱，绿色叶形代表同心协力建设绿色首尔的美好希望。</p><p>继“热爱首尔”活动之后，还陆续举行了“热爱首尔，热爱公交”、“热爱首尔，热爱地铁”等活动，持续地进行大范围的公益广告宣传。</p><p>首尔市一共拥有大约8000辆公共汽车。在宜传城市形象方面，这8000个移动的宣传大使比任何电视节目、报纸广告都更具影响力。</p><h2 id="吸引外资-实现双赢" tabindex="-1">吸引外资，实现双赢 <a class="header-anchor" href="#吸引外资-实现双赢" aria-label="Permalink to &quot;吸引外资，实现双赢&quot;">​</a></h2><p>常言道：三个臭皮匠，赛过诸葛亮。这个道理也适用于公共部门和民间部门的相互协作。</p><p>公共部门和民间部门积极合作，往往能达到公共部门或民间部门单枪匹马所不能企及的效果。为此，民间部门也应该表现出不亚于公共部门的积极性。</p><p>在全球化时代，无论对一个国家，还是对一个城市而言，吸引外资的重要性都不言而喻。从这个层面上来说，首尔市吸引美国国际集团（AIG）投资，在汝矣岛设立首尔国际金融中心（SIFC）</p><p>具有极为重要的意义。</p><p>2006年6月5日举行开工典礼首尔国际金融中心计划是一个占地超过3万坪的大型开发项目，由54层OFFICE塔等三座顶级写字楼和一座国际酒店组成。如果能吸引国际性的金融企业、金融服务机构、跨国企业亚洲区总部进驻中心，将对首尔市确立东北亚金融中心的地位产生关键性的作用。</p><p>长期以来我一直大声疾呼吸引外资，但公共部门直接出面吸引外资的例子还是屈指可数。这次首尔市从AIG集团吸引了相当于14亿美元的直接投资，真可谓少见壮举。AIG集团是全球著名的国际性保险及金融服务机构，是全球第一大保险集团、第二大金融集团。此次成功合作的推动力正是来自于首尔市公务员积极企业意识。</p><p>把首尔打造为国际金融中心——这并不是我一个人的抱负，以前的首尔市政府也为此做出了很多努力。但是，实际看到的成果却很少。</p><p>“怎么才能尽快把首尔打造成金融中心呢？”</p><p>光喊口号是没有用的。为了能看到成果，有关负责人多方筹谋，但进展并不顺利。事实上，这样的目标也不可能一蹴而就，需要长期坚持不懈地努力促进。</p><p>正当我们陷于无处施展的苦恼中时，我听到了销售位于汝矣岛的首尔市占地的消息。这一块占地曾经用作中小企业的展会场所，在中小企业撤走之后，便成了闲置土地。为了不浪费资源，市政府暂定将其出售给外部。</p><p>“汝矣岛是韩国的金融中心，我们能不能把外资吸引到这里来？”</p><p>我向有关负责人说出了我的想法。负责的局长是一位富有事业心的领导。在听了我的建议之后，他马上表现出积极的态度，说要试一试。由法律、财务、咨询等领域的专家组成的策划小组很快着手展开了工作。</p><p>在吸引资本方面，市政厅的公务员们完全是门外汉。但我们并没有完全委托外面的咨询机构，具体工作仍是在市政厅的主导下进行。这为公务员们提供了一个积累相关经验绝好机会。</p><p>“市长，我想去一趟日本。”</p><p>不久后，局长说要直接去见AIG集团的首席副社长，探一探他们的意向。不巧的是，当时日本国内正在与SARS奋战。局长在这种情况下去了日本，在他的努力下，事情终于有了一线希望。</p><p>AIG集团派出一支小组赴首尔考察。正准备进行协商的时候，恰好AIG集团的会长访问首尔，我们便有了见面详谈的机会。</p><p>“汝矣岛在韩国金融界的位置是排在第一位的。如果AIG集团在汝矣岛投资成立金融中心，对首尔和AIG集团都会有可观的前景。”</p><p>“我们的考察组正在商讨之中，相信马上就会有好消息的。”</p><p>给听到AIG集团会长的这句话，我似乎看到了成功的曙光。</p><p>AIG集团决定组建企业集团，负责首尔国际金融中心的建设和运营。从完全出售还是出租占地的问题开始，双方需要协商的水问题可谓千丝万缕。不知道是不是因为这个原因，我感觉协商组有些着急。我找来负责的局长，叮嘱他再怎么着急也不能放弃实际利益。</p><p>“从其他国家吸引外资的情况来看，以免费提供的居多，其实完全没有那种必要。请好好判断一下我们的有利之处再进行协商。”</p><p>协商组的专家们进行了充分准备，以干练的姿态，与AIG集团展开了历时一年多协商。拉锯式的谈判历经曲折、却没有走向决裂，是因为双方之间存在着最基本的信任。</p><p>经过一年多的艰苦协商，首尔市和AIG集团最终达成了共识。</p><p>首尔市向AIG集团出租占地100年，具有每年80亿元以上的出租收益和选择权，AIG集团在10年内不得抽走自身的回收资本。</p><p>吸引AIG集团投资对首尔市来说具有几方面的特殊意义。首先，作为地方自治团体，吸引了相当于14亿美元的投资，这绝对是一次了不起的成就，其次，我们不是通过出售，而是通过出租收益等方式，在协商过程中积极争取了自身的实际利益：另外，对首尔的公务员来说，这次协商的成功让他们积累了丰富的经验，也增强了依靠自身力量吸引外资的信心。</p><p>在全球化时代，公共部门和民间部门之间的界限逐渐消失了。</p><p>如果公共部门和民间部门通力合作，就能节约国民税收，提高工作效率。民选三期市政府积极推动与企业合作、吸引企业投资，也正是出于这样的目的。</p><p>同样地，吸引外国企业投资也能达成首尔市政府与企业双赢。正如在吸引AIG集团投资的事例中看到的那样，如果公务员具有经营意识和促进能力，不仅能与本土企业携手共进，还能创造出与世界性企业合作的良好效果。</p><p><img src="'+C+'" alt="总统选举游说" loading="lazy"></p><p>总统选举游说卸任首尔市长后，政绩卓著的李明博决定参加韩国总统选举。他用一年多时间，考察了欧洲的运河政策和科学城市、美国的大城市行政、迪拜的城市革命，努力寻找着大韩民国成长的动力。</p><p><img src="'+G+'" alt="大国家党党内竞选人在一起" loading="lazy"></p><p>大国家党党内竞选人在一起</p><p><img src="'+T+'" alt="2007年8月20日大国家党党内竞选结果公布之后，与朴槿惠在一起" loading="lazy"></p><p>2007年8月20日大国家党党内竞选结果公布之后，与朴槿惠在一起</p><p><img src="'+S+'" alt="李明博在竞选活动中举起拇指" loading="lazy"></p><p>李明博在竞选活动中举起拇指在2007年5月正式开始的大国家党党内预备竞选中，李明博和朴谨惠成为最具实力的候选人。8月20日，李明博最终赢得党内预选，正式成为大国家党第17届总统候选人。</p><p>李明博领导才能的源泉，是在战胜极度贫困的过程中形成的白手起家的斗志，是领导一个员工不足百名的中小企业成长为拥有超过16万员工的大型跨国企业的挑战精神，是在首尔公务员组织中注入经营意识、提高行政效率的革新精神。</p><p>与此相契合，韩国国民对李明博最大的期待是“振兴经济”。在总统竞选中，李明博提出了旨在加强市场竞争、实现经济增长的“747发展计划”，即：韩国将实现7％的年均经济增长率，10年后人均收入达到4万美元，韩国将发展为世界第7大经济体。其具体设想为：开凿连接首尔和釜山的“韩半岛大运河”，帮助建立以釜山、大邱、光州、大田为中心的广域经济圈，实现地区均衡发展；削减福利服务行业的工作岗位，转而向各界人士提供创业基金；减少大企业的营业税和经营限制，推动国营银行私有化；稳定中产阶级数量，建立“温暖的市场经济”；允许大学实行自主招生，要求政府负担贫困家庭的教育费用；在全国范围内建立国际科学与商业城市，通过提升设计与创新能力，增加制造业的竞争力等。</p><p><img src="'+D+'" alt="李明博获美国TIME杂志评选的国际环境英雄奖" loading="lazy"></p><p>李明博获美国TIME杂志评选的国际环境英雄奖</p><p><img src="'+E+'" alt="参加第17届总统选举宣言" loading="lazy"></p><p>参加第17届总统选举宣言</p><p><img src="'+O+'" alt="韩国中央选举管理委员会颁发给李明博的总统当选证" loading="lazy"></p><p>韩国中央选举管理委员会颁发给李明博的总统当选证</p><p><img src="'+W+'" alt="李明博当选总统后参拜国立墓地时的留言" loading="lazy"></p><p>李明博当选总统后参拜国立墓地时的留言2007年12月19日，第17届韩国总统选举结果最终揭晓：总投票数23732854票，李明博获得了其中的11492389票。李明博以48.7％的高支持率，当选为韩国新一届总统。</p><p><img src="'+F+'" alt="会见安倍晋三" loading="lazy"></p><p>会见安倍晋三</p><p><img src="'+K+'" alt="会见卡拉姆" loading="lazy"></p><p>会见卡拉姆曾经创造了“工薪族神话”、“清溪川神话”的李明博，实现了其精彩人生中最耀眼的一次飞跃。</p>',342)])])}const Z=a(v,[["render",w]]);export{V as __pageData,Z as default};
